import { useState, useEffect, useCallback } from "react";

// Wails v3 bindings – ES module imports generated by `wails3 generate bindings`.
import { Backend } from "../api/backend";

// Connection state types
export interface ConnectionInfo {
  state: "disconnected" | "connecting" | "connected" | "offline";
  server_url?: string;
  user_name?: string;
  user_email?: string;
  workspace?: string;
}

/**
 * The desktop connection lifecycle used by the ServerConnect gate (App.tsx):
 * probe/refresh state, PKCE login, workspace selection, and disconnect. All
 * other server reads/writes flow through the composite ApiAdapter now, not
 * per-domain hooks — this is the one hook the shell still needs.
 */
export function useConnection() {
  const [info, setInfo] = useState<ConnectionInfo>({ state: "disconnected" });

  const refresh = useCallback(async () => {
    const ci = (await Backend.GetConnectionState()) as ConnectionInfo;
    setInfo(ci);
    return ci;
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const connect = useCallback(
    async (serverURL: string) => {
      await Backend.ConnectToServer(serverURL);
      return refresh();
    },
    [refresh],
  );

  const startLogin = useCallback(async (serverURL: string): Promise<void> => {
    await Backend.StartLogin(serverURL);
  }, []);

  const waitForLogin = useCallback(async (): Promise<boolean> => {
    return Backend.WaitForLogin() as Promise<boolean>;
  }, []);

  const cancelLogin = useCallback(async () => {
    await Backend.CancelLogin();
  }, []);

  const logout = useCallback(async () => {
    await Backend.Logout();
    setInfo({ state: "disconnected" });
  }, []);

  const disconnect = useCallback(async () => {
    await Backend.Disconnect();
    setInfo({ state: "disconnected" });
  }, []);

  const selectWorkspace = useCallback(
    async (slug: string) => {
      await Backend.SelectWorkspace(slug);
      return refresh();
    },
    [refresh],
  );

  const getServerWorkspaces = useCallback(async () => {
    return Backend.GetServerWorkspaces() as Promise<
      Array<{
        id: string;
        slug: string;
        name: string;
        description: string;
        role: string;
      }>
    >;
  }, []);

  return {
    info,
    refresh,
    connect,
    startLogin,
    waitForLogin,
    cancelLogin,
    logout,
    disconnect,
    selectWorkspace,
    getServerWorkspaces,
  };
}
